  Lemma aimg_client_w_img : forall lo hi a, aimg_client_w lo hi -> lo <= a < hi -> ARW_LO <= a < AIMG_TOP /\ ~ astatic a.
  Proof.
    intros lo hi a W Ha. unfold aimg_client_w, ATLS_PRIV_LO, ATLS_PRIV_HI, ALIBC_PGSZ, ATSD0, AsIface.ATP in W.
    unfold ARW_LO, AIMG_TOP, astatic, AINST, AFLAGS, ACFLAGS, ASHBASE_CELL, AHIGHMEMEND, ACANPOISON, AINITED, AALLOCFLAGS, AIAINIT, AHOOKS,
      AREALMEMSET, AIAINST, AGOT_LO, APAGESZ, ASECNAME, APRIMNAME, ATLSSLOT, ATSD, ALSANDIS, AGOT2, OI_MISMATCH.
    split; [lia|]. intros X. repeat (destruct X as [X|X]); lia.
  Qed.

  Lemma client_window_bridge : forall x LB m iv,
    as_RHEAP (KHp p) x LB m -> AsIface.aclient_write_ok (KHp p) LB iv -> AllocRep.aclient_write_ok (i_s x) (lbp LB) iv.
  Proof.
    intros x LB m [lo hi] R CW.
    pose proof R as (HA & IDS & LEN & AWV & FLX & DEP0 & DPL & DTR & DJ1 & DJ2 & EF & MF & DJD & TH & TLS & ASV & DAP & DSEC & PINV & SPR). pose proof (proj1 DAP) as DSB.
    destruct HA as (AR & ND & EQ). pose proof (proj1 AR) as OK.
    unfold AsIface.aclient_write_ok in CW. cbn [fst snd] in CW.
    destruct CW as [C|[C|[(b & Hb & C1 & C2)|[(b & Hb & C1 & C2)|[C|[C|C]]]]]]; cbn [as_FSB KHp] in *; unfold AsIface.AFS_SIZE, AllocRep.AFS_SIZE in *.
    - left. exact C.
    - right; right; right; left. cbn [fst snd].
      pose proof C as C'. unfold aimg_client_w, ATLS_PRIV_LO, ATLS_PRIV_HI, ALIBC_PGSZ, ATSD0, AsIface.ATP in C'. unfold ARW_LO, AIMG_TOP.
      split; [lia|]. split; [lia|]. intros a Ha. exact (proj2 (aimg_client_w_img lo hi a C Ha)).
    - right; left. exists (blk_addr b, blk_size b). split; [unfold lbp; apply in_map_iff; exists b; auto|]. cbn [fst snd]. lia.
    - right; right; left. exists (blk_addr b, blk_size b). split; [unfold lbp; apply in_map_iff; exists b; auto|]. cbn [fst snd]. lia.
    - right; right; right; right. cbn [fst snd]. intros a Ha. apply (fakestack_not_afoot _ OK). rewrite EF. unfold AllocRep.AFS_SIZE, AsIface.AFS_SIZE in *. lia.
    - right; right; right; right. cbn [fst snd]. intros a Ha. apply (shadow_windows_not_afoot _ OK). right. rewrite EF. unfold AllocRep.AFS_SIZE, AsIface.AFS_SIZE in *. lia.
    - right; right; right; right. cbn [fst snd]. intros a Ha. apply (shadow_windows_not_afoot _ OK). left. lia.
  Qed.

